import{_ as i,a as t}from"./chunks/git_github_2.d-LBDz3k.js";import{_ as s,a,b as n}from"./chunks/git_12.qPcW1yq5.js";import{_ as r,c as o,o as l,ag as u}from"./chunks/framework.BtwP-r-R.js";const p="/14B-POO-A26/assets/git_config_main.B9wdlI1Q.png",c="/14B-POO-A26/assets/git_push.QxC2OoKk.png",F=JSON.parse('{"title":"Git avec Visual Studio et GitHub  Pour un travail individuel","description":"","frontmatter":{},"headers":[],"relativePath":"git_github.md","filePath":"git_github.md"}'),d={name:"git_github.md"};function g(h,e,m,f,v,k){return l(),o("div",null,[...e[0]||(e[0]=[u('<h1 id="git-avec-visual-studio-et-github-pour-un-travail-individuel" tabindex="-1">Git avec Visual Studio et GitHub <br><small> Pour un travail individuel </small> <a class="header-anchor" href="#git-avec-visual-studio-et-github-pour-un-travail-individuel" aria-label="Permalink to &quot;Git avec Visual Studio et GitHub &lt;br&gt;&lt;small&gt; Pour un travail individuel &lt;/small&gt;&quot;">​</a></h1><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Installez ou mettez à jour Git : <a href="http://git-scm.com/downloads" target="_blank" rel="noreferrer">http://git-scm.com/downloads</a></p><ul><li>Ne pas changer les options par défaut lors de l&#39;installation.</li></ul><h2 id="configuration-prealable-de-git" tabindex="-1">Configuration préalable de Git <a class="header-anchor" href="#configuration-prealable-de-git" aria-label="Permalink to &quot;Configuration préalable de Git&quot;">​</a></h2><h3 id="renommer-la-branche-principale-en-«-main-»" tabindex="-1">Renommer la branche principale en « main » <a class="header-anchor" href="#renommer-la-branche-principale-en-«-main-»" aria-label="Permalink to &quot;Renommer la branche principale en « main »&quot;">​</a></h3><p>Il s&#39;agit de modifier les configurations globales de Git sur votre Visual Studio afin de nommer la branche principale par défaut <strong>main</strong> de tous vos projets suivis:</p><ul><li><p>À partir du menu <code>Outils &gt; Options</code>.</p></li><li><p>Dans la colonne de gauche, allez jusqu&#39;à <code>Contrôle de code source &gt; Paramètres Git &gt; Configuration Globale Git</code>.</p></li><li><p>Renseignez le champ : <code>Nom de branche par défaut</code> avec la valeur <strong>main</strong></p><p><img src="'+p+'" alt="Renommer la branche en main"></p></li></ul><p><strong>Note :</strong> Il n&#39;est pas nécessaire de répéter cette étape à chaque fois que vous suivrez un nouveau projet avec Git.</p><h2 id="configuration-initiale" tabindex="-1">Configuration initiale <a class="header-anchor" href="#configuration-initiale" aria-label="Permalink to &quot;Configuration initiale&quot;">​</a></h2><ul><li><p>Si ce n&#39;est pas déjà fait, créez-vous un compte sur le cloud GitHub.com (<a href="https://github.com/" target="_blank" rel="noreferrer">https://github.com/</a>).</p></li><li><p>Effectuez les opérations suivantes dans l&#39;ordre :</p><ol><li>Ouvrir le projet Visual Studio existant et sélectionner le menu <code>Git &gt; créer un dépôt Git</code></li></ol><p><img src="'+i+'" alt="Nouveau projet github"></p><ol start="2"><li>Séctionner le modèle .gitignore par défaut de Visual Studio</li><li>Se connecter à son compte GitHub (à partir de Visual Studio), indiquer le nom du dépôt et cocher la case &quot;<strong>Dépôt privé</strong>&quot;</li></ol><p><img src="'+t+'" alt="Nouveau projet github"></p><ol start="4"><li>Cliquer sur le bouton <code>Créer et envoyer (push)</code></li></ol><p><img src="'+c+'" alt="Nouveau projet github"></p></li></ul><h2 id="ignorer-des-fichier-gitignore" tabindex="-1">Ignorer des fichier (.gitignore) <a class="header-anchor" href="#ignorer-des-fichier-gitignore" aria-label="Permalink to &quot;Ignorer des fichier (.gitignore)&quot;">​</a></h2><p>Ce fichier permet d&#39;ignorer certains fichiers de votre solution afin qu&#39;ils ne soient pas publiés sur le dépôt distant. Ceci évite de partager des fichiers qui risquent de créer des conflits dans le cas d&#39;un travail collaboratif mais aussi des fichiers « inutiles » qui encombrent vos dépôts distants et ralentissent les transferts.</p><p>Le fichier doit être nommé « <strong>.gitignore</strong> » . Si vous ne l&#39;avez pas fait lors de la création du dépôt, voici comment faire.</p><p>Vous devez :</p><ol><li>Cliquer sur l&#39;option « <strong>…</strong> » à partir du menu « <strong>Gérer les dépôt distants …</strong> ».</li></ol><p><img src="'+s+'" alt="Nouveau projet git la"></p><ol start="2"><li>Vous devez par la suite sélectionner dans le menu, l&#39;option <strong>Paramètres du dépôt Git -&gt; Général</strong>. Dans la section, « <strong>Git files</strong> », cliquez sur le bouton « <strong>Ajouter</strong> » vis-à-vis Ingorer le fichier:</li></ol><p><img src="'+a+'" alt="Nouveau projet git la"></p><h2 id="comment-faire-pour-conserver-des-versions-de-fichier-localement" tabindex="-1">Comment faire pour conserver des versions de fichier localement? <a class="header-anchor" href="#comment-faire-pour-conserver-des-versions-de-fichier-localement" aria-label="Permalink to &quot;Comment faire pour conserver des versions de fichier localement?&quot;">​</a></h2><ul><li><p>À partir de l&#39;onglet &quot;Modification Git&quot;:</p><ul><li>Ajoutez (aux changements indexés) les fichiers que vous voulez suivre à partir de la section contenant les modifications.</li><li>Indiquez le texte du &quot;<strong>Commit</strong>&quot; (Celui-ci doit être significatif, voir <a href="#quand-faire-un-commit">les bonnes pratiques Git</a>).</li><li>Sélectionnez les fichiers à ajouter au commit.</li><li>Cliquez sur « <strong>Valider Tout</strong> ».</li></ul><p><img src="'+n+`" alt="Nouveau projet git la"></p><ul><li>Pour mettre à jour le dépôt distant, cliquez sur le lien « <strong>Envoyer</strong> ».</li></ul></li></ul><h2 id="quand-faire-un-commit" tabindex="-1">Quand faire un commit <a class="header-anchor" href="#quand-faire-un-commit" aria-label="Permalink to &quot;Quand faire un commit&quot;">​</a></h2><ul><li><p><strong>Petites étapes significatives</strong> : Il est recommandé de faire un commit chaque fois que vous avez atteint un point stable dans votre travail, même si la fonctionnalité n&#39;est pas entièrement terminée. Par exemple, après avoir ajouté une fonction ou corrigé un bug.</p></li><li><p><strong>Unité logique de travail</strong> : Le commit doit représenter une unité logique de travail. Évitez de mélanger plusieurs modifications sans lien dans un seul commit (par exemple, éviter de corriger un bug et d&#39;ajouter une nouvelle fonctionnalité dans le même commit).</p></li><li><p><strong>Tests réussis :</strong> Faites un commit lorsque vous avez testé votre code et que tout fonctionne correctement (ou au moins fonctionne comme prévu).</p></li><li><p><strong>Messages clairs</strong> : Les messages de commit doivent être descriptifs, expliquant ce qui a été modifié et pourquoi.</p></li></ul><p>Une bonne description de commit doit comprendre deux parties :</p><ul><li>Un message de titre clair (maximum 50 caractères recommandé)</li><li>Une description plus détaillée (<strong>optionnelle</strong>) qui explique davantage le &quot;pourquoi&quot; du changement, et non seulement le &quot;quoi&quot;.</li></ul><p><strong>structure d&#39;un commit</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&gt;(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">portée facultative</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description courte</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description détaillée (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">optionnelle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Types de commits courants :</p><ul><li><strong>feat</strong> : pour une nouvelle fonctionnalité.</li><li><strong>fix</strong> : pour une correction de bug.</li><li><strong>chore</strong> : pour les changements de configuration ou maintenance qui n&#39;affectent pas le code de production (par ex., mise à jour des dépendances).</li><li><strong>docs</strong> : pour des modifications concernant la documentation.</li><li><strong>style</strong> : pour des changements de formatage ou de <strong>style de code</strong> (qui ne modifient pas le comportement du code. ex. supprimer les sauts de ligne inutiles, corriger l&#39;indentation, etc.).</li><li><strong>refactor</strong> : pour une refonte du code qui n&#39;ajoute pas de nouvelles fonctionnalités ni ne corrige de bugs.</li><li><strong>test</strong> : pour ajouter ou modifier des tests.</li><li><strong>perf</strong> : pour améliorer les performances.</li></ul><p>Voici un exemple :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feat(auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): Ajout de la fonctionnalité de connexion utilisateur</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ajoute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonctionnalité</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d&#39;authentification de base, permettant aux utilisateurs de se connecter. Il inclut le formulaire de connexion, l&#39;intégration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l&#39;API et la gestion des erreurs.</span></span></code></pre></div><h3 id="bonne-pratiques-generales" tabindex="-1">Bonne pratiques générales <a class="header-anchor" href="#bonne-pratiques-generales" aria-label="Permalink to &quot;Bonne pratiques générales&quot;">​</a></h3><ul><li><p><strong>Utiliser l&#39;impératif présent</strong> : Les messages de commit doivent être rédigés à l’impératif, comme si vous donniez un ordre au système. Exemple : &quot;Ajout de la fonctionnalité de connexion&quot;</p></li><li><p><strong>Clarté et concision</strong> : Soyez clair sur ce que vous avez fait et pourquoi. Un bon titre de commit doit être compréhensible sans avoir besoin de consulter le code lui-même.</p></li><li><p><strong>Des messages courts pour le titre</strong> : Limitez le titre à 50 caractères pour qu&#39;il reste lisible. Utilisez la description pour des détails supplémentaires si nécessaire.</p></li><li><p><strong>Séparer les commits logiquement</strong> : Un commit doit correspondre à un seul changement logique. Ne mélangez pas plusieurs modifications sans lien dans un seul commit.</p></li></ul><h2 id="quand-faire-un-push" tabindex="-1">Quand faire un push <a class="header-anchor" href="#quand-faire-un-push" aria-label="Permalink to &quot;Quand faire un push&quot;">​</a></h2><ul><li><p><strong>Travail terminé ou stable</strong> : Faites un push lorsque vous avez atteint une étape significative, comme une fonctionnalité terminée, ou lorsque le code est stable et ne casse rien.</p></li><li><p><strong>Partager votre travail</strong> : Si vous travaillez en équipe, il est important de faire un push régulièrement pour partager vos changements avec vos coéquipiers et éviter les conflits lors des fusions.</p></li><li><p><strong>Avant de commencer une nouvelle tâche</strong> : Avant de vous lancer dans une nouvelle fonctionnalité ou correction de bug, assurez-vous de faire un push pour sauvegarder et synchroniser votre travail en cours.</p></li><li><p><strong>S&#39;assurer que les autres peuvent accéder à votre travail</strong> : Si vous devez quitter votre poste ou que vous travaillez depuis différents ordinateurs, faites un push pour sauvegarder votre code sur le dépôt distant.</p></li></ul><h2 id="liens-utiles" tabindex="-1">Liens utiles <a class="header-anchor" href="#liens-utiles" aria-label="Permalink to &quot;Liens utiles&quot;">​</a></h2><ul><li>Documentation officielle de Git : <a href="https://git-scm.com/doc" target="_blank" rel="noreferrer">https://git-scm.com/doc</a></li><li>Cours rapide sur Git en 15 minutes : <a href="https://try.github.io/levels/1/challenges/1" target="_blank" rel="noreferrer">https://try.github.io/levels/1/challenges/1</a></li><li>Cours sur Git (niveau 1 gratuit) : <a href="http://gitreal.codeschool.com/levels/1" target="_blank" rel="noreferrer">http://gitreal.codeschool.com/levels/1</a></li><li>Cours sur Git et GitHub sur OpenClassRooms : <a href="https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github" target="_blank" rel="noreferrer">https://openclassrooms.com/courses/gerer-son-code-avec-git-et-github</a></li></ul>`,37)])])}const C=r(d,[["render",g]]);export{F as __pageData,C as default};
